from convert.adapters.base.ReadOptions import ReadOptions
from convert.adapters.solidworks.Container.Container import SldprtArchive
from convert.adapters.solidworks.Core.Adapter import ReadNativePart, SldprtAdapter
from interchange.document.Behavior.DocumentIo import ToJson
from interchange.document.Models.DocumentModel import CadDocument


# strict re reading the generated bytes detects every source field omitted by the neutral projection
def CheckRevRead(DocumentValue: CadDocument, Payload: bytes) -> None:
    SourceName = DocumentValue.source.path
    Expected = ReadNativePart(
        SldprtAdapter(),
        SldprtArchive.from_bytes(Payload, SourceName),
        Payload,
        SourceName,
        ReadOptions(strict=True, include_brep=DocumentValue.brep is not None),
    )
    if ToJson(DocumentValue, IndentSize=None) != ToJson(Expected, IndentSize=None):
        raise ValueError(
            "SOLIDWORKS revolve readback differs from its regenerated part"
        )
